import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

public class Main {
    public static void main(String[] args) throws Exception {
        Path input = Path.of("students.csv");
        List<String> rows = List.of("id,name,mark", "1,Ada,91", "2,Grace,87");
        Files.write(input, rows);
        try {
            for (String row : Files.readAllLines(input).stream().skip(1).toList()) {
                String[] fields = row.split(",", -1);
                if (fields.length != 3) throw new IllegalArgumentException("Bad CSV row: " + row);
                int mark = Integer.parseInt(fields[2]);
                if (mark < 0 || mark > 100) throw new IllegalArgumentException("Invalid mark: " + mark);
                System.out.println(fields[1] + " -> " + mark);
            }
        } finally {
            Files.deleteIfExists(input);
        }
    }
}
